package com.spring.spring_rest.dto;

import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.Size;

/**
 * Data transfer object for student data sent to and from the client
 * as JSON. Keeps the database entity separate from the API and holds
 * the validation rules checked when {@code @Valid} is used.
 */
public class StudentDto {

    /** The student id, generated by the database. */
    private Long id;

    /** The first name. Must be 2 to 50 characters if provided. */
    @Size(min = 2, max = 50, message = "Must be 2 to 50 characters")
    private String firstName;

    /** The last name. Must be 2 to 50 characters if provided. */
    @Size(min = 2, max = 50, message = "Must be 2 to 50 characters")
    private String lastName;

    /** The email address. Required, not blank, and a valid format. */
    @Email(message="Email is required and should be valid")
    private String email;
    
    /**
     * Creates a student DTO with all of its values.
     *
     * @param id the student id
     * @param firstName the student's first name
     * @param lastName the student's last name
     * @param email the student's email address
     */
    public StudentDto(Long id, String firstName, 
                    String lastName, String email) {
        this.id = id;
        this.firstName = firstName;
        this.lastName = lastName;
        this.email = email;
    }

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getFirstName() {
        return firstName;
    }

    public void setFirstName(String firstName) {
        this.firstName = firstName;
    }

    public String getLastName() {
        return lastName;
    }

    public void setLastName(String lastName) {
        this.lastName = lastName;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

}
